import torch.nn as nn
import torch.nn.functional as F
import torch.distributed as dist


def _dist_is_available():
    return dist.is_available() and dist.is_initialized()


def _get_world_size():
    if _dist_is_available():
        return dist.get_world_size()
    return 1


def _get_rank():
    if _dist_is_available():
        return dist.get_rank()
    return 0


class _AllReduceSum(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input_tensor):
        world_size = _get_world_size()
        ctx.world_size = world_size
        if world_size == 1:
            return input_tensor
        output = input_tensor.contiguous().clone()
        dist.all_reduce(output)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        if ctx.world_size == 1:
            return grad_output
        grad = grad_output.contiguous().clone()
        dist.all_reduce(grad)
        return grad


class _AllGatherLastDim(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input_tensor):
        world_size = _get_world_size()
        rank = _get_rank()
        ctx.world_size = world_size
        ctx.rank = rank
        ctx.local_dim = input_tensor.shape[-1]
        if world_size == 1:
            return input_tensor
        gather_list = [torch.empty_like(input_tensor) for _ in range(world_size)]
        dist.all_gather(gather_list, input_tensor)
        output = torch.cat(gather_list, dim=-1)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        world_size = ctx.world_size
        if world_size == 1:
            return grad_output
        local_dim = ctx.local_dim
        rank = ctx.rank
        start = rank * local_dim
        end = start + local_dim
        grad_input = grad_output[..., start:end].contiguous()
        dist.all_reduce(grad_input)
        return grad_input


class ColumnParallelLinear(nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _get_world_size()
        self.rank = _get_rank()

        if master_weight.dim() != 2:
            raise ValueError("master_weight must be 2D")

        if master_weight.shape == (out_features, in_features):
            self._weight_transposed = True
            self._out_dim = 0
        elif master_weight.shape == (in_features, out_features):
            self._weight_transposed = False
            self._out_dim = 1
        else:
            raise ValueError(
                "master_weight shape must be (out_features, in_features) or (in_features, out_features)"
            )

        if self.world_size > 1:
            if out_features % self.world_size != 0:
                raise ValueError("out_features must be divisible by world_size")
            weight_chunks = torch.chunk(master_weight, self.world_size, dim=self._out_dim)
            weight_shard = weight_chunks[self.rank]
        else:
            weight_shard = master_weight

        self.weight = nn.Parameter(weight_shard.contiguous().clone().detach())

        if bias:
            local_out_features = self.weight.shape[self._out_dim]
            self.bias = nn.Parameter(
                torch.zeros(
                    local_out_features,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.bias = None

    def forward(self, input_tensor):
        if self._weight_transposed:
            output_local = F.linear(input_tensor, self.weight, self.bias)
        else:
            output_local = input_tensor.matmul(self.weight)
            if self.bias is not None:
                output_local = output_local + self.bias
        if self.world_size == 1:
            return output_local
        return _AllGatherLastDim.apply(output_local)


class RowParallelLinear(nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _get_world_size()
        self.rank = _get_rank()

        if master_weight.dim() != 2:
            raise ValueError("master_weight must be 2D")

        if master_weight.shape == (out_features, in_features):
            self._weight_transposed = True
            self._in_dim = 1
        elif master_weight.shape == (in_features, out_features):
            self._weight_transposed = False
            self._in_dim = 0
        else:
            raise ValueError(
                "master_weight shape must be (out_features, in_features) or (in_features, out_features)"
            )

        if self.world_size > 1:
            if in_features % self.world_size != 0:
                raise ValueError("in_features must be divisible by world_size")
            weight_chunks = torch.chunk(master_weight, self.world_size, dim=self._in_dim)
            weight_shard = weight_chunks[self.rank]
        else:
            weight_shard = master_weight

        self.weight = nn.Parameter(weight_shard.contiguous().clone().detach())

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.bias = None

    def forward(self, input_tensor):
        if self.world_size > 1:
            input_chunks = torch.chunk(input_tensor, self.world_size, dim=-1)
            input_local = input_chunks[self.rank]
        else:
            input_local = input_tensor

        if self._weight_transposed:
            output_local = F.linear(input_local, self.weight, None)
        else:
            output_local = input_local.matmul(self.weight)

        if self.world_size > 1:
            output = _AllReduceSum.apply(output_local)
        else:
            output = output_local

        if self.bias is not None:
            output = output + self.bias
        return output
